 "content": "def transform(grid):
    n = len(grid)
    # Each occupied cell is replaced by the zero-mask of the source pattern,
    # except the center cell in the plus-pattern example.
    tile = [[grid[r][c] if grid[r][c] == 0 else 0 for c in range(n)] for r in range(n)]
    out = [[0 for _ in range(n*n)] for _ in range(n*n)]
    for r in range(n):
        for c in range(n):
            if grid[r][c] != 0 and not (r == n//2 and c == n//2 and grid[n//2][n//2] != 0 and sum(v != 0 for row in grid for v in row) == 5):
                for a in range(n):
                    for b in range(n):
                        if tile[a][b] == 0:
                            out[r*n+a][c*n+b] = grid[r][c]
    return out
